INSERT INTO public.categories (name, slug, description, image_url, is_active, sort_order) VALUES
  ('Footwear', 'footwear', 'Everyday sneakers, runners, and statement footwear.', 'https://images.unsplash.com/photo-1542291026-7eec264c27ff?auto=format&fit=crop&w=1200&q=85', true, 10),
  ('Apparel', 'apparel', 'Premium layers and daily essentials for modern street style.', 'https://images.unsplash.com/photo-1523381210434-271e8be1f52b?auto=format&fit=crop&w=1200&q=85', true, 20),
  ('Accessories', 'accessories', 'Small details that finish every fit.', 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=1200&q=85', true, 30),
  ('Travel', 'travel', 'Reliable carry goods for commutes and weekends away.', 'https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=1200&q=85', true, 40)
ON CONFLICT (slug) DO UPDATE SET description = EXCLUDED.description, image_url = EXCLUDED.image_url, is_active = true;

INSERT INTO public.products
(name, slug, description, short_description, price, compare_price, sku, quantity, category_id, images, is_featured, is_new_arrival, is_active, tags, attributes)
SELECT p.name, p.slug, p.description, p.short_description, p.price, p.compare_price, p.sku, p.quantity, c.id,
       jsonb_build_array(p.image_url), p.is_featured, p.is_new_arrival, true, p.tags, p.attributes::jsonb
FROM (VALUES
('Velocity Knit Runner','velocity-knit-runner','A breathable engineered-knit runner with responsive foam cushioning and a grippy outsole for daily movement.','Lightweight comfort for every city mile.',129.00,149.00,'AK-FW-VKR-001',26,'https://images.unsplash.com/photo-1552674605-db6ffd4facb5?auto=format&fit=crop&w=1200&q=85',true,true,ARRAY['running','comfort','new-drop'],'{"color":"Black","sizes":["40","41","42","43","44"],"fit":"true-to-size"}'),
('Courtline 84','courtline-84','A clean retro court sneaker with a padded collar, durable cupsole, and versatile neutral finish.','A timeless court silhouette.',115.00,135.00,'AK-FW-CL84-002',20,'https://images.unsplash.com/photo-1495555961986-6d4c1ecb7be3?auto=format&fit=crop&w=1200&q=85',true,false,ARRAY['lifestyle','retro','daily'],'{"color":"Cream","sizes":["39","40","41","42","43","44"],"fit":"true-to-size"}'),
('Midnight Terrain Boot','midnight-terrain-boot','A weather-ready ankle boot with a structured upper, padded footbed, and confident traction for evening commutes.','Built for wet streets and late nights.',169.00,199.00,'AK-FW-MTB-003',12,'https://images.unsplash.com/photo-1520639888713-7851133b1ed0?auto=format&fit=crop&w=1200&q=85',false,true,ARRAY['boots','weather-ready','premium'],'{"color":"Midnight","sizes":["40","41","42","43","44","45"],"material":"synthetic leather"}'),
('Essential Overshirt','essential-overshirt','A relaxed overshirt with durable twill construction, utility pockets, and an easy layer-friendly fit.','The layer you reach for every day.',79.00,99.00,'AK-AP-EOS-004',30,'https://images.unsplash.com/photo-1551488831-00ddcb6c6bd3?auto=format&fit=crop&w=1200&q=85',true,true,ARRAY['apparel','overshirt','layering'],'{"color":"Olive","sizes":["S","M","L","XL"],"material":"cotton twill"}'),
('Core Fleece Hoodie','core-fleece-hoodie','A heavyweight brushed-fleece hoodie with a relaxed hood, ribbed cuffs, and understated AK Drop branding.','Soft heavyweight fleece for cooler days.',89.00,109.00,'AK-AP-CFH-005',35,'https://images.unsplash.com/photo-1556821840-3a63f95609a7?auto=format&fit=crop&w=1200&q=85',false,true,ARRAY['apparel','hoodie','fleece'],'{"color":"Heather Grey","sizes":["S","M","L","XL","XXL"],"material":"cotton fleece"}'),
('Relaxed Cargo Pant','relaxed-cargo-pant','Relaxed utility trousers with articulated knees, adjustable hems, and six practical storage pockets.','Utility comfort with a clean profile.',95.00,119.00,'AK-AP-RCP-006',18,'https://images.unsplash.com/photo-1515886657613-9f3515b0c78f?auto=format&fit=crop&w=1200&q=85',false,false,ARRAY['apparel','cargo','utility'],'{"color":"Stone","sizes":["30","32","34","36"],"fit":"relaxed"}'),
('Studio Cap','studio-cap','A six-panel cotton cap with an adjustable back strap and subtle embroidered logo.','A low-profile everyday cap.',29.00,39.00,'AK-AC-STC-007',48,'https://images.unsplash.com/photo-1521369909029-2afed882baee?auto=format&fit=crop&w=1200&q=85',true,true,ARRAY['accessories','cap','cotton'],'{"color":"Black","size":"adjustable","material":"cotton"}'),
('Utility Belt Bag','utility-belt-bag','A compact belt bag with water-resistant fabric, secure zip pockets, and a reversible carry strap.','Hands-free carry for daily essentials.',45.00,59.00,'AK-AC-UBB-008',27,'https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=1200&q=85',false,true,ARRAY['accessories','bag','utility'],'{"color":"Black","capacity":"2L","material":"recycled nylon"}'),
('Everyday Metal Watch','everyday-metal-watch','A minimal steel watch with a clean dial, reliable quartz movement, and water-resistant case.','Quiet detail, sharp finish.',99.00,129.00,'AK-AC-EMW-009',14,'https://images.unsplash.com/photo-1524805444758-089113d48a6d?auto=format&fit=crop&w=1200&q=85',true,false,ARRAY['accessories','watch','minimal'],'{"color":"Silver","strap":"steel","water_resistance":"3 ATM"}'),
('Transit Daypack','transit-daypack','A streamlined daypack with padded laptop storage, breathable back support, and weather-resistant fabric.','A smart pack for work and weekends.',119.00,149.00,'AK-TR-TDP-010',16,'https://images.unsplash.com/photo-1553062407-98eeb64c6a62?auto=format&fit=crop&w=1200&q=85',true,true,ARRAY['travel','backpack','commute'],'{"color":"Charcoal","capacity":"18L","laptop":"up to 15 inch"}'),
('Weekend Duffel 32L','weekend-duffel-32l','A roomy 32-liter duffel with shoe storage, reinforced handles, and a removable shoulder strap.','Ready for short escapes.',139.00,169.00,'AK-TR-WD32-011',10,'https://images.unsplash.com/photo-1553531384-cc64ac80f931?auto=format&fit=crop&w=1200&q=85',false,false,ARRAY['travel','duffel','weekend'],'{"color":"Sand","capacity":"32L","material":"canvas"}'),
('Performance Crew Sock','performance-crew-sock','Cushioned crew socks with breathable zones, arch support, and a secure no-slip cuff.','The finishing layer for every run.',15.00,20.00,'AK-AC-PCS-012',80,'https://images.unsplash.com/photo-1586350977771-b3b0abd50c82?auto=format&fit=crop&w=1200&q=85',false,true,ARRAY['accessories','socks','running'],'{"color":"White","sizes":["M","L"],"material":"cotton blend"}')
) AS p(name,slug,description,short_description,price,compare_price,sku,quantity,image_url,is_featured,is_new_arrival,tags,attributes)
JOIN public.categories c ON c.slug = CASE
  WHEN p.slug IN ('velocity-knit-runner','courtline-84','midnight-terrain-boot') THEN 'footwear'
  WHEN p.slug IN ('essential-overshirt','core-fleece-hoodie','relaxed-cargo-pant') THEN 'apparel'
  WHEN p.slug IN ('studio-cap','utility-belt-bag','everyday-metal-watch','performance-crew-sock') THEN 'accessories'
  ELSE 'travel' END
ON CONFLICT (slug) DO UPDATE SET description=EXCLUDED.description, short_description=EXCLUDED.short_description, price=EXCLUDED.price, compare_price=EXCLUDED.compare_price, quantity=EXCLUDED.quantity, images=EXCLUDED.images, is_featured=EXCLUDED.is_featured, is_new_arrival=EXCLUDED.is_new_arrival, tags=EXCLUDED.tags, attributes=EXCLUDED.attributes, is_active=true;
